def path_sum_brute(root, target_sum):
    all_paths = []
    def collect(node, path):
        if node is None:
            return
        path.append(node.val)
        if node.left is None and node.right is None:
            all_paths.append(list(path))                 # collect EVERY path, regardless of sum
        else:
            collect(node.left, path)
            collect(node.right, path)
        path.pop()
    collect(root, [])
    return [p for p in all_paths if sum(p) == target_sum]     # filter AFTERWARD

