def path_sum(root, target_sum):
    result = []
    path = []
    def dfs(node, remaining):
        if node is None:
            return
        path.append(node.val)
        remaining -= node.val                                   # track remaining sum incrementally
        if node.left is None and node.right is None and remaining == 0:
            result.append(list(path))                            # save a COPY, only for valid paths
        else:
            dfs(node.left, remaining)
            dfs(node.right, remaining)
        path.pop()                                                # backtrack
    dfs(root, target_sum)
    return result

