import java.util.*;

public class Main {
    static List<List<Integer>> result = new ArrayList<>();
    static List<Integer> path = new ArrayList<>();

    static List<List<Integer>> pathSum(TreeNode root, int targetSum) {
        dfs(root, targetSum);
        return result;
    }

    static void dfs(TreeNode node, int remaining) {
        if (node == null) return;
        path.add(node.val);
        remaining -= node.val;                                       // track remaining sum incrementally
        if (node.left == null && node.right == null && remaining == 0) {
            result.add(new ArrayList<>(path));                          // save a COPY, only for valid paths
        } else {
            dfs(node.left, remaining);
            dfs(node.right, remaining);
        }
        path.remove(path.size() - 1);                                  // backtrack
    }
}

